import Complex128Array = require( '@stdlib/array/complex128' );
import zgemv = require( './index' );


// TESTS //

// The function returns a Complex128Array...
{
	const x = new Complex128Array( 10 );
	const y = new Complex128Array( 10 );
	const A = new Complex128Array( 20 );

	zgemv( 'row-major', 'no-transpose', 10, 10, 1.0, A, 3, x, 1, 1.0, y, 1 ); // $ExpectType Complex128Array
}

// The compiler throws an error if the function is provided a first argument which is not a string...
{
	const x = new Complex128Array( 10 );
	const y = new Complex128Array( 10 );
	const A = new Complex128Array( 20 );

	zgemv( 10, 'no-transpose', 10, 10, 1.0, A, 3, x, 1, 1.0, y, 1 ); // $ExpectError
	zgemv( '10', 'no-transpose', 10, 10, 1.0, A, 3, x, 1, 1.0, y, 1 ); // $ExpectError
	zgemv( true, 'no-transpose', 10, 10, 1.0, A, 3, x, 1, 1.0, y, 1 ); // $ExpectError
	zgemv( false, 'no-transpose', 10, 10, 1.0, A, 3, x, 1, 1.0, y, 1 ); // $ExpectError
	zgemv( null, 'no-transpose', 10, 10, 1.0, A, 3, x, 1, 1.0, y, 1 ); // $ExpectError
	zgemv( undefined, 'no-transpose', 10, 10, 1.0, A, 3, x, 1, 1.0, y, 1 ); // $ExpectError
	zgemv( [], 'no-transpose', 10, 10, 1.0, A, 3, x, 1, 1.0, y, 1 ); // $ExpectError
	zgemv( {}, 'no-transpose', 10, 10, 1.0, A, 3, x, 1, 1.0, y, 1 ); // $ExpectError
	zgemv( ( x: number ): number => x, 'no-transpose', 10, 10, 1.0, A, 3, x, 1, 1.0, y, 1 ); // $ExpectError
}

